        if(g.has_draft_children)add(actions,btn('验证映射',async()=>{await api('tracking/groups/'+g.id+'/validate-split','POST');notice('三个子组映射验证通过')}),btn('激活拆分',async()=>{const children=t.groups.filter(x=>x.parent_id===g.id&&x.status==='DRAFT').map(x=>x.path);if(!await ask({title:'激活拆分',description:'父组：'+g.path+'\n子组：'+children.join('、')+'\n将重新分配 '+g.token_count+' 个 Token。其他分支不会变化。',danger:true,label:'确认激活'}))return;const x=await api('tracking/groups/'+g.id+'/activate-split','POST');await show('入口追踪');notice('拆分已激活，重新分配 '+x.moved+' 个 Token')}));
        add(actions,btn('查看Token',()=>{tokenGroupFilter=String(g.id);show('Token')}));const state=g.status==='ACTIVE'?(g.has_active_children?'已拆分':g.has_draft_children?'待激活':'已启用'):stateLabels[g.status]||'其他状态';return[g.path,state,g.token_count,g.mapping_count,fmtTime(g.created_at),fmtTime(g.split_at),actions]
    })))
}
